mapper.select:
SELECT poll.poll_id, poll.question, poll.poll_status, poll.allow_multiple, poll.max_selections, poll.realtime_results, poll.ends_at, poll.result_published_at, poll.created_by, member.member_name AS creator_name, poll.created_at FROM polls poll JOIN members member ON member.member_id = poll.created_by WHERE poll.use_yn = 'Y'
AND CASE WHEN poll.poll_status = 'OPEN' AND COALESCE(poll.ends_at, DATE_ADD(poll.created_at, INTERVAL 60 MINUTE)) <= UTC_TIMESTAMP(6) THEN 'CLOSED' ELSE poll.poll_status END = #{status}
ORDER BY poll.created_at DESC, poll.poll_id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM poll_options
WHERE poll_id = #{pollId}
  AND poll_option_id IN

      #{pollOptionId}

SELECT COUNT(*) FROM poll_ballots
WHERE poll_id = #{pollId}
  AND (visitor_key = #{visitorKey} OR member_id = #{memberId})

mapper.update:
UPDATE polls
SET question = #{question}, allow_multiple = #{allowMultiple}, max_selections = #{maxSelections},
    realtime_results = #{realtimeResults}, ends_at = #{endsAt}
WHERE poll_id = #{pollId}
